import{_ as t,o as p,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"缓冲流","description":"","frontmatter":{"title":"缓冲流","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/05-IO 与 File/缓冲流.md","filePath":"posts/java快速入门/第三部分：核心 API/05-IO 与 File/缓冲流.md"}'),i={name:"posts/java快速入门/第三部分：核心 API/05-IO 与 File/缓冲流.md"};function u(d,e,n,c,a,l){return p(),o("div",null,[...e[0]||(e[0]=[r('<div><p>缓冲流<code>,</code>也叫高效流，是对<code>4</code>个基本的 <code>FileXxx</code> 流的增强，所以也是<code>4</code>个流，按照数据类型分类： <strong>字节缓冲流</strong>： <code>BufferedInputStream</code> ， <code>BufferedOutputStream</code><strong>字符缓冲流</strong>： <code>BufferedReader</code> ， <code>BufferedWriter</code> 缓冲流的基本原理，是在创建流对象时，会创建一个内置的默认大小的缓冲区数组，通过缓冲区读写，减少系统<code>IO</code>次数，从而提高读写的效率。</p><p><strong>字节缓冲流</strong><strong>构造方法</strong><code>public BufferedInputStream(InputStream in)</code> ：创建一个 新的缓冲输入流。 <code>public BufferedOutputStream(OutputStream out)</code> ： 创建一个新的缓冲输出流。 构造举例，代码如下：</p><p>// 创建字节缓冲输入流</p><p>BufferedInputStream bis = new BufferedInputStream(new FileInputStream(&quot;bis.txt&quot;)); // 创建字节缓冲输出流</p><p>BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(&quot;bos.txt&quot;)); <strong>效率测试</strong> 查询<code>API</code>，缓冲流读写方法与基本的流是一致的，我们通过复制大文件（<code>375MB</code>），测试它的效率。</p><p><code>1.</code></p><p>基本流，代码如下：</p><p>public class BufferedDemo { public static void main(String[] args) throws FileNotFoundException { // 记录开始时间</p><p>long start = System.currentTimeMillis(); // 创建流对象</p><p>try ( FileInputStream fis = new FileInputStream(&quot;jdk9.exe&quot;); FileOutputStream fos = new FileOutputStream(&quot;copy.exe&quot;) ){ // 读写数据</p><p>int b; while ((b = fis.read()) != ‐</p><ol><li>{ fos.write(b); } } catch (IOException e) { e.printStackTrace(); } // 记录结束时间</li></ol><p>long end = System.currentTimeMillis(); System.out.println(&quot; 普通流复制时间</p><p><code>:&quot;+(end</code></p><p>‐</p><p><code>start)+&quot;</code></p><p>毫秒</p><p>&quot;); } } 十几分钟过去了</p><ul><li>...</li><li><ol start="2"><li></li></ol></li></ul><p>缓冲流，代码如下：</p><p>public class BufferedDemo { public static void main(String[] args) throws FileNotFoundException { // 记录开始时间</p><p>long start = System.currentTimeMillis(); // 创建流对象</p><p>try ( BufferedInputStream bis = new BufferedInputStream(new FileInputStream(&quot;jdk9.exe&quot;)); BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(&quot;copy.exe&quot;)); ){// 读写数据</p><p>int b; while ((b = bis.read()) != ‐</p><ol><li>{ bos.write(b); } } catch (IOException e) { e.printStackTrace(); } // 记录结束时间</li></ol><p>long end = System.currentTimeMillis(); System.out.println(&quot; 缓冲流复制时间</p><p><code>:&quot;+(end</code></p><p>‐</p><p><code>start)+&quot;</code></p><p>毫秒</p><p>&quot;); } } 缓冲流复制时间</p><p><code>:8016</code></p><p>毫秒</p><p>如何更快呢？ 使用数组的方式，代码如下：</p><p>public class BufferedDemo { public static void main(String[] args) throws FileNotFoundException { // 记录开始时间</p><p>long start = System.currentTimeMillis(); // 创建流对象</p><p>try ( BufferedInputStream bis = new BufferedInputStream(new FileInputStream(&quot;jdk9.exe&quot;)); BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(&quot;copy.exe&quot;)); ){ // 读写数据</p><p>int len; byte[] bytes = new byte[8*1024]; while ((len = bis.read(bytes)) != ‐</p><ol><li>{ bos.write(bytes, 0 , len); } } catch (IOException e) { e.printStackTrace(); } // 记录结束时间</li></ol><p>long end = System.currentTimeMillis(); System.out.println(&quot; 缓冲流使用数组复制时间</p><p><code>:&quot;+(end</code></p><p>‐</p><p><code>start)+&quot;</code></p><p>毫秒</p><p>&quot;); } } 缓冲流使用数组复制时间</p><p><code>:666</code></p><p>毫秒</p><p><strong>字符缓冲流</strong><strong>构造方法</strong></p><p>public BufferedReader(Reader in) ：创建一个新的缓冲输入流。 <code>public BufferedWriter(Writer out)</code> ： 创建一个新的缓冲输出流。构造举例，代码如下：</p><p>// 创建字符缓冲输入流</p><p>BufferedReader br = new BufferedReader(new FileReader(&quot;br.txt&quot;)); // 创建字符缓冲输出流</p><p>BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;bw.txt&quot;)); <strong>特有方法</strong> 字符缓冲流的基本方法与普通字符流调用方式一致，不再阐述，我们来看它们具备的特有方法。</p><p><code>BufffferedReader</code></p><p>： <code>public String readLine() :</code> 读一行文字。</p><p><code>BufffferedWriter</code></p><p>： <code>public void newLine() :</code> 写一行行分隔符<code>,</code>由系统属性定义符号。</p><p><code>readLine</code></p><p>方法演示，代码如下：</p><p>public class BufferedReaderDemo { public static void main(String[] args) throws IOException { // 创建流对象</p><p>BufferedReader br = new BufferedReader(new FileReader(&quot;in.txt&quot;)); // 定义字符串<code>,</code>保存读取的一行文字</p><p>String line = null; // 循环读取<code>,</code>读取到最后返回</p><p>null while ((line = br.readLine())!=null) { System.out.print(line); System.out.println(&quot; ‐‐‐‐‐‐</p><p>&quot;); } // 释放资源</p><p>br.close(); } }</p><p><code>newLine</code> 方法演示，代码如下：</p><p>public class BufferedWriterDemo throws IOException { public static void main(String[] args) throws IOException { // 创建流对象</p><p>BufferedWriter bw = new BufferedWriter(new FileWriter(&quot;out.txt&quot;)); // 写出数据</p><p><code>bw.write(&quot;</code></p><p>黑马</p><p>&quot;); // 写出换行</p><p>bw.newLine(); bw.write(&quot; 程序</p><p>&quot;); bw.newLine(); bw.write(&quot; 员</p><p>&quot;); bw.newLine(); // 释放资源</p><p>bw.close(); } } 输出效果<code>:</code> 黑马程序 员</p></div>',1)])])}const m=t(i,[["render",u]]);export{f as __pageData,m as default};
